import{_ as p,a0 as r,w as h,s as o,ao as l,I as n,x as a,a1 as i,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const B=JSON.parse('{"title":"Bash 基礎知識系列 #5：在 Bash 中使用數組 | LCTT x X-CMD","titleTemplate":false,"description":"Bash 基礎知識系列 #5：在 Bash 中使用數組 | LCTT (202307) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Bash 基礎知識系列 #5：在 Bash 中使用數組 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Bash 基礎知識系列 #5：在 Bash 中使用數組 | LCTT (202307) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202307/20230710.1 ⭐️ Bash Basics Series 5 Using Arrays in Bash","title":"Bash 基礎知識系列 #5：在 Bash 中使用數組","tag":"202307","desc":""},"relativePath":"202307/20230710.1 ⭐️ Bash Basics Series 5 Using Arrays in Bash.md","filePath":"[post].md"}'),d={name:"202307/20230710.1 ⭐️ Bash Basics Series 5 Using Arrays in Bash.md"};function g(b,s,k,u,c,m){const e=r("Link");return h(),o("div",null,[s[23]||(s[23]=l('<h1 id="bash-基礎知識系列-5-在-bash-中使用數組" tabindex="-1">Bash 基礎知識系列 #5：在 Bash 中使用數組 <a class="header-anchor" href="#bash-基礎知識系列-5-在-bash-中使用數組" aria-label="Permalink to “Bash 基礎知識系列 #5：在 Bash 中使用數組”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202307/20/150302ttfmzchutthfcncm.jpg" alt=""></p><blockquote><p>本章將介紹如何在 Bash Shell 腳本中使用數組。學習添加元素、刪除元素和獲取數組長度。</p></blockquote><p>在本系列的前面部分中，你瞭解了變量。變量中可以有單個值。</p><p>數組內部可以有多個值。當你必須一次處理多個變量時，這會使事情變得更容易。你不必將各個值存儲在新變量中。</p><p>因此，不要像這樣聲明五個變量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>distro1=Ubuntu</span></span>\n<span class="line"><span>distro2=Fedora</span></span>\n<span class="line"><span>distro3=SUSE</span></span>\n<span class="line"><span>distro4=Arch Linux</span></span>\n<span class="line"><span>distro5=Nix</span></span></code></pre></div><p>你可以在單個數組中初始化它們所有：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>distros=(Ubuntu Fedora SUSE &quot;Arch Linux&quot; Nix)</span></span></code></pre></div><p>與其他一些編程語言不同，你不使用逗號作為數組元素分隔符。</p><p>那挺好的。讓我們看看如何訪問數組元素。</p><h3 id="在-bash-中訪問數組元素" tabindex="-1">在 Bash 中訪問數組元素 <a class="header-anchor" href="#在-bash-中訪問數組元素" aria-label="Permalink to “在 Bash 中訪問數組元素”">​</a></h3><p>使用索引（數組中的位置）訪問數組元素。要訪問索引 N 處的數組元素，請使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>${array_name[N]}</span></span></code></pre></div><blockquote><p>💡 與大多數其他編程語言一樣，Bash Shell 中的數組從索引 0 開始。這意味着第一個元素的索引為 0，第二個元素的索引為 1，第 n 個元素的索引為 <code>n-1</code>。</p></blockquote><p>因此，如果你想打印 SUSE，你將使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo ${distros[2]}</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/07/accessing-array-elements-bash.png" alt="Example of accessing array elements in bash shell"></p><blockquote><p>🚧 <code>${</code> 之後或 <code>}</code> 之前不能有任何空格。你不能像 <code>${ array[n] }</code> 那樣使用它。</p></blockquote><h3 id="一次訪問所有數組元素" tabindex="-1">一次訪問所有數組元素 <a class="header-anchor" href="#一次訪問所有數組元素" aria-label="Permalink to “一次訪問所有數組元素”">​</a></h3><p>假設你要打印數組的所有元素。</p><p>你可以一一使用 <code>echo ${array[n]}</code> 但這確實沒有必要。有一個更好更簡單的方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>${array[*]}</span></span></code></pre></div><p>這將為你提供所有數組元素。</p><p><img src="https://itsfoss.com/content/images/2023/07/accessing-all-array-elements-bash.png" alt="Accessing all array elements at once in bash shell"></p><h3 id="在-bash-中獲取數組長度" tabindex="-1">在 Bash 中獲取數組長度 <a class="header-anchor" href="#在-bash-中獲取數組長度" aria-label="Permalink to “在 Bash 中獲取數組長度”">​</a></h3>',26)),n("p",null,[s[1]||(s[1]=a("如何知道數組中有多少個元素？ 有一個專門的方法 ",-1)),i(e,{href:"https://linuxhandbook.com:443/array-length-bash/"},{default:t(()=>[...s[0]||(s[0]=[a("在 Bash 中獲取數組長度",-1)])]),_:1}),s[2]||(s[2]=a("：",-1))]),s[24]||(s[24]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>${#array_name[@]}</span></span></code></pre></div><p>就這麼簡單，對吧？</p><p><img src="https://itsfoss.com/content/images/2023/07/get-array-length-bash.png" alt="Get array length in bash"></p><h3 id="在-bash-中添加數組元素" tabindex="-1">在 Bash 中添加數組元素 <a class="header-anchor" href="#在-bash-中添加數組元素" aria-label="Permalink to “在 Bash 中添加數組元素”">​</a></h3>',4)),n("p",null,[s[4]||(s[4]=a("如果必須向數組添加其他元素，請使用 ",-1)),s[5]||(s[5]=n("code",null,"+=",-1)),s[6]||(s[6]=a(" 運算符 ",-1)),i(e,{href:"https://linuxhandbook.com:443/bash-append-array/"},{default:t(()=>[...s[3]||(s[3]=[a("將元素追加到 Bash 中的現有數組",-1)])]),_:1}),s[7]||(s[7]=a("：",-1))]),s[25]||(s[25]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>array_name+=(&quot;new_value&quot;)</span></span></code></pre></div><p>這是一個例子：</p><p><img src="https://itsfoss.com/content/images/2023/07/append-element-to-array.png" alt="Append new element to array"></p><blockquote><p>🚧 追加元素時使用 <code>()</code> 很重要。</p></blockquote><p>你還可以使用索引將元素設置在任何位置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>array_name[N]=new_value</span></span></code></pre></div><p><strong>但請記住使用正確的索引編號。</strong> 如果在現有索引上使用它，新值將替換該元素。</p><p>如果你使用“越界”索引，它仍會添加到最後一個元素之後。例如，如果數組長度為 6，並且你嘗試在索引 9 處設置新值，則該值仍將作為最後一個元素添加到第 7 個位置（索引 6）。</p><p><img src="https://itsfoss.com/content/images/2023/07/add-array-element-bash-1.png" alt=""></p><h3 id="刪除數組元素" tabindex="-1">刪除數組元素 <a class="header-anchor" href="#刪除數組元素" aria-label="Permalink to “刪除數組元素”">​</a></h3><p>你可以使用 Shell 內置的 <code>unset</code> 通過提供索引號來刪除數組元素：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>unset array_name[N]</span></span></code></pre></div><p>這是一個示例，我刪除了數組的第四個元素。</p><p><img src="https://itsfoss.com/content/images/2023/07/delete-array-element-bash.png" alt="Delete array element in bash"></p><p>你還可以通過 unset 來刪除整個數組：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>unset array_name</span></span></code></pre></div><blockquote><p>💡 Bash 中沒有嚴格的數據類型規則。你可以創建一個同時包含整數和字符串的數組。</p></blockquote><h3 id="🏋️-練習時間" tabindex="-1">🏋️ 練習時間 <a class="header-anchor" href="#🏋️-練習時間" aria-label="Permalink to “🏋️ 練習時間”">​</a></h3><p>讓我們練習一下你所學到的有關 Bash 數組的知識。</p><p><strong>練習 1</strong>：創建一個 Bash 腳本，其中包含五個最佳 Linux 發行版的數組。全部打印出來。</p><p>現在，用 “Hannah Montanna Linux” 替換中間的選擇。</p><p><strong>練習 2</strong>：創建一個 Bash 腳本，該腳本接受用户提供的三個數字，然後以相反的順序打印它們。</p><p>預期輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Enter three numbers and press enter</span></span>
<span class="line"><span>12 23 44</span></span>
<span class="line"><span>Numbers in reverse order are: 44 23 12</span></span></code></pre></div><p>我希望你喜歡通過本系列學習 Bash Shell 腳本。在下一章中，你將學習如何使用 <code>if-else</code>。敬請關注。</p><p><em>（題圖：MJ/09477e2f-2bf9-4fdf-bc1e-c894a068adf2）</em></p><hr>`,27)),n("p",null,[s[9]||(s[9]=a("via: ",-1)),i(e,{href:"https://itsfoss.com/bash-arrays/"},{default:t(()=>[...s[8]||(s[8]=[a("https://itsfoss.com/bash-arrays/",-1)])]),_:1})]),n("p",null,[s[14]||(s[14]=a("作者：",-1)),i(e,{href:"https://itsfoss.com/author/abhishek/"},{default:t(()=>[...s[10]||(s[10]=[a("Abhishek Prakash",-1)])]),_:1}),s[15]||(s[15]=a(" 選題：",-1)),i(e,{href:"https://github.com/lkxed/"},{default:t(()=>[...s[11]||(s[11]=[a("lkxed",-1)])]),_:1}),s[16]||(s[16]=a(" 譯者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:t(()=>[...s[12]||(s[12]=[a("geekpi",-1)])]),_:1}),s[17]||(s[17]=a(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[13]||(s[13]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[20]||(s[20]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[18]||(s[18]=[a("LCTT",-1)])]),_:1}),s[21]||(s[21]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:t(()=>[...s[19]||(s[19]=[a("Linux中國",-1)])]),_:1}),s[22]||(s[22]=a(" 榮譽推出",-1))])])}const x=p(d,[["render",g]]);export{B as __pageData,x as default};
